float field(vec3 p)
{
    vec3 q = abs(fract(p * 0.7) - 0.5);
    return length(q) - 0.2;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.0, iTime * 1.2);
    vec3 rd = normalize(vec3(uv, 1.0));
    float t = 0.0;
    float glow = 0.0;
    for (int i = 0; i < 48; i++) {
        float d = field(ro + rd * t);
        glow += 0.02 / (0.05 + abs(d));
        if (d < 0.001 || t > 30.0) { break; }
        t += d;
    }
    vec3 haze = vec3(0.10, 0.14, 0.30);
    vec3 col = haze * exp(-0.08 * t) + vec3(0.9, 0.5, 0.2) * glow * 0.05;
    fragColor = vec4(col, 1.0);
}
